await expect(page.getByRole('button', { name: city.name, exact: true })).toBeVisible(); await page.getByRole('button', { name: building.name, exact: true }).click(); await page.getByRole('button', { name: event.name, exact: true }).click(); await expect(page.locator('#entity-name')).toHaveValue(event.name); await editData(page, { ...event.data, summary: textToRichText('場所一覧から同じ建物の出来事を編集した。') }); await page.getByRole('button', { name: '詳細を閉じる', exact: true }).click(); await world(page, '地図・場所・移動');
    const createMap = async (name: string, placeId: string, parentId = '') => { await page.getByRole('button', { name: '地図を追加', exact: true }).click(); const modal = page.getByRole('dialog', { name: '地図と場所の階層', exact: true }); await modal.getByLabel('地図の名前', { exact: true }).fill(name); await modal.getByLabel('地図の対象となる場所', { exact: true }).selectOption(placeId); await modal.getByLabel('地図の画像', { exact: true }).selectOption(attachment.id); if (parentId) await modal.getByLabel('親の地図', { exact: true }).selectOption(parentId); await modal.getByRole('button', { name: '地図を保存', exact: true }).click(); await expect(modal).toBeHidden(); return storedNamed(page, name, 'map'); };
    const cityMap = await createMap('街の実画像地図', city.id); cityMapId = cityMap.id; const buildingMap = await createMap('建物の実画像地図', building.id, cityMap.id); buildingMapId = buildingMap.id; await page.getByLabel('表示する地図', { exact: true }).selectOption(cityMapId); await page.getByLabel('地図へピンを追加する場所', { exact: true }).selectOption(building.id); await page.getByLabel('地図ピンの横位置', { exact: true }).fill('0.25'); await page.getByLabel('地図ピンの縦位置', { exact: true }).fill('0.75'); await page.getByRole('button', { name: 'ピン座標を適用', exact: true }).click(); await page.getByRole('button', { name: 'ピンの変更を保存', exact: true }).click(); await expect.poll(async () => (await storedEntity(page, cityMapId, 'map')).data.pins).toMatchObject([{ placeId: building.id, x: .25, y: .75 }]);
